Section Target.
Variables (malloc : Z -> M St (option P)) (free : P -> M St unit) (nh : M St Empty_set) (emit : Z -> M St unit).

(* [comment removed for export] *)
Hypothesis Um : forall Y v w n, 0 <= n <= REQMAX -> HISTOK (n :: sizes Y) ->
  TSM (fun RNG A s mo => JX Y v w RNG A s mo /\ n <= v /\ 1 <= w) (malloc n)
      (fun r RNG A s mo => exists q, r = Some q /\ JX ((q, n) :: Y) (v - n) (w - 1) RNG A s mo /\ n < 2^63).
Hypothesis Uf : forall Y v w p n, TSM (JX ((p, n) :: Y) v w) (free p) (fun _ => JX Y v w).
Hypothesis Unh : forall Y v w (Q : postM Empty_set), TSM (JX Y v w) nh Q.
Hypothesis Uemit : forall Y v w z, TSJ Y v w (emit z).

(* [comment removed for export] *)
Lemma malloc_seq {X} Y v w n (k : option P -> M St X) (Q : postM X) :
  0 <= n <= REQMAX -> HISTOK (n :: sizes Y) ->
  (forall q, n < 2^63 -> TSM (JX ((q, n) :: Y) (v - n) (w - 1)) (k (Some q)) Q) ->
