Definition RUN_COST : Z := MAX_INPUT + 4 * FUZZ_COST.

Theorem target_run_ok : forall X cfg payload v w, (length X <= 1)%nat -> zlength payload <= MAX_INPUT -> RUN_COST <= v -> RUN_OPS <= w ->
  TSM (JX X v w) (target_run malloc free fuzz1 emit cfg payload) (fun _ => JX X (v - RUN_COST) (w - RUN_OPS)).
